cat > /tmp/tobs4-scripts/natspec.py <<'EOF'
import glob, json, sys, re
root = sys.argv[1]
files = {"src/Raffle.sol", "src/RaffleFactory.sol", "src/interfaces/IRaffle.sol", "src/interfaces/IRaffleFactory.sol", "src/libraries/RaffleConstants.sol"}
seen = {}
for bi in glob.glob(f"{root}/out/build-info/*.json"):
    d = json.load(open(bi))
    out = d.get("output", d)
    for path, src in out.get("sources", {}).items():
        if path in files and path not in seen:
            seen[path] = src["ast"]
KINDS = {"FunctionDefinition", "EventDefinition", "ErrorDefinition", "VariableDeclaration", "StructDefinition", "EnumDefinition", "ModifierDefinition", "ContractDefinition", "EnumValue"}
total = 0; missing = []; tagissues = []
def doc_text(n):
    d = n.get("documentation")
    if isinstance(d, dict): return d.get("text", "")
    return d or ""
def walk(n, path, parent_kind=None):
    global total
    if isinstance(n, dict):
        t = n.get("nodeType")
        is_state = t == "VariableDeclaration" and n.get("stateVariable")
        if t in KINDS and (t != "VariableDeclaration" or is_state):
            total += 1
            name = n.get("name") or n.get("kind")
            txt = doc_text(n)
            if not txt and t != "EnumValue":
                missing.append(f"{path}: {t} {name}")
            if t in ("FunctionDefinition", "EventDefinition", "ErrorDefinition") and txt and "@inheritdoc" not in txt:
                for p in n.get("parameters", {}).get("parameters", []):
                    if p.get("name") and f"@param {p['name']}" not in txt:
                        tagissues.append(f"{path}: {name} missing @param {p['name']}")
                if t == "FunctionDefinition":
                    rets = n.get("returnParameters", {}).get("parameters", [])
                    if rets and "@return" not in txt:
                        tagissues.append(f"{path}: {name} missing @return")
        for k, v in n.items():
            if k != "documentation":
                walk(v, path, t)
    elif isinstance(n, list):
        for x in n: walk(x, path, parent_kind)
for p, ast in sorted(seen.items()):
    walk(ast, p)
print("files parsed:", sorted(seen))
print("documentable declarations:", total)
print("missing NatSpec:", len(missing)); [print("  ", m) for m in missing]
print("tag issues:", len(tagissues)); [print("  ", m) for m in tagissues]
EOF
SCR2=$(cat /tmp/tobs4-scratch2-path); python3 -I /tmp/tobs4-scripts/natspec.py "$SCR2"

